<script setup>
import {computed,ref,onMounted,onUnmounted} from 'vue';
import api from '../../services/api';
import Icon from '../rise/RiseIcon.vue';
import PublicWebsiteContactForm from '../public/PublicWebsiteContactForm.vue';
import PublicProviderProfileEditor from '../publicServices/PublicProviderProfileEditor.vue';
import {buildPublicIntakeUrl} from '../../utils/publicIntakeUrl';
import {history,vision,mission,goals,values,highlights,duties,expectations,selectInternshipJobs,trainingPeople,publicProfileIntroduction,internshipSupervisors} from './itscoInternshipContent';
const props=defineProps({section:{type:String,default:'internships'},data:{type:Object,required:true},preview:Boolean});
defineEmits(['saved']);
const path=slug=>`/p/itsco/${slug}`;
const internshipUrl='https://www.itsco.health/internships';
const pages=[['The program','internships'],['Our founders','founders'],['Supervisors & mentors','supervisors'],['Fair display','internship-fair']];
const heroes={internships:{title:'Learn. Connect. Make a difference.',body:'Practicum and internship experiences that put learning, mentorship, and meaningful mental health care at the center.',note:'Grow your skills. Support your community.'},founders:{title:'Our founders.',body:'A shared vision. A stronger tomorrow. Meet Rachel Finch and Michael Mendez, the founders of ITSCO.',note:'Care for clients. Care for clinicians.'},supervisors:{title:'Guidance that helps you grow.',body:'Supervision, mentorship, and a team committed to your development as a mental health professional.',note:'Ask questions. Build confidence. Keep learning.'}};
const hero=computed(()=>heroes[props.section]||heroes.internships);
const people=computed(()=>trainingPeople(props.data));
const founders=computed(()=>['Rachel Finch','Michael Mendez'].map(name=>people.value.find(p=>p.displayName===name)||{displayName:name}));
const supervisors=computed(()=>internshipSupervisors(props.data));
const mentors=computed(()=>people.value.filter(p=>/\bmentor\b|clinical practice assistant/i.test(p.title)));
const initials=name=>name.split(' ').map(v=>v[0]).slice(0,2).join('');
const jobs=ref([]),jobsLoading=ref(true),jobsError=ref(false),fullscreen=ref(false),displayError=ref('');let disposed=false;
const internshipJobs=computed(()=>selectInternshipJobs(jobs.value));
async function loadJobs(){jobsLoading.value=true;jobsError.value=false;try{const r=await api.get('/public-intake/careers/itsco',{skipAuthRedirect:true});if(!disposed)jobs.value=Array.isArray(r.data?.jobs)?r.data.jobs:[];}catch{if(!disposed)jobsError.value=true;}finally{if(!disposed)jobsLoading.value=false;}}
function fullscreenChanged(){fullscreen.value=Boolean(document.fullscreenElement);}
async function toggleFullscreen(){displayError.value='';try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else displayError.value='For a larger iPad display, hide the browser toolbar or add this page to your Home Screen.';}catch{displayError.value='Full screen is unavailable in this browser. The fair display still works in this tab.';}}
function printFair(){window.print();}
onMounted(()=>{loadJobs();document.addEventListener('fullscreenchange',fullscreenChanged);});
onUnmounted(()=>{disposed=true;document.removeEventListener('fullscreenchange',fullscreenChanged);});
</script>
